fn cleanup(b: &[u8], c: &mut Candidate2048) -> bool {
    if b.len() != ARENA_BYTES {
        return false;
    }
    let zero = [0u8; 8];
    for i in 0..256 {
        let at = i * 8;
        c[at..at + 8].copy_from_slice(&zero);
    }
    for i in 0..12 {
        let source = SCALAR.base + CELLS[i] * 8;
        let destination = 888 + i * 8;
        // Both cells already encode one canonical LE u64: this complete8-byte
        // load/restore needs no scalar decode/re-encode or array return place.
        c[destination..destination + 8].copy_from_slice(&b[source..source + 8]);
    }
    #[cfg(test)]
    if CLEANUP_FAULT.swap(false, std::sync::atomic::Ordering::Relaxed) {
        c[0] = 0x51;
        return false;
    }
    true
}

